/* benchmark: 5-body gravity (generated by trith/bench/gen.py) */
#include <math.h>
#include <stdio.h>

#define DT (1.0 / 81.0)

static void pair(double *a, int i, int j) {
    double dx = a[7 * i] - a[7 * j];
    double dy = a[7 * i + 1] - a[7 * j + 1];
    double dz = a[7 * i + 2] - a[7 * j + 2];
    double d2 = dx * dx + dy * dy;
    double d2b = d2 + dz * dz;
    double mag = DT / (d2b * sqrt(d2b));
    double mi = a[7 * i + 6], mj = a[7 * j + 6];
    a[7 * i + 3] = a[7 * i + 3] - dx * mj * mag;
    a[7 * i + 4] = a[7 * i + 4] - dy * mj * mag;
    a[7 * i + 5] = a[7 * i + 5] - dz * mj * mag;
    a[7 * j + 3] = a[7 * j + 3] + dx * mi * mag;
    a[7 * j + 4] = a[7 * j + 4] + dy * mi * mag;
    a[7 * j + 5] = a[7 * j + 5] + dz * mi * mag;
}

static void advance(double *a) {
    pair(a, 0, 1);
    pair(a, 0, 2);
    pair(a, 0, 3);
    pair(a, 0, 4);
    pair(a, 1, 2);
    pair(a, 1, 3);
    pair(a, 1, 4);
    pair(a, 2, 3);
    pair(a, 2, 4);
    pair(a, 3, 4);
    for (int b = 0; b < 5; b++) {
        for (int f = 0; f < 3; f++) {
            a[7 * b + f] = a[7 * b + f] + DT * a[7 * b + 3 + f];
        }
    }
}

int main(void) {
    double a[35] = {
    (0.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (9.0 / 1.0),
    (3.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (5.0 / 3.0), (0.0 / 1.0), (1.0 / 27.0),
    (-6.0 / 1.0), (1.0 / 3.0), (0.0 / 1.0), (0.0 / 1.0), (-4.0 / 3.0), (1.0 / 9.0), (1.0 / 9.0),
    (0.0 / 1.0), (10.0 / 1.0), (-1.0 / 3.0), (-1.0 / 1.0), (0.0 / 1.0), (0.0 / 1.0), (1.0 / 3.0),
    (0.0 / 1.0), (-14.0 / 1.0), (2.0 / 3.0), (7.0 / 9.0), (0.0 / 1.0), (-1.0 / 27.0), (2.0 / 9.0)
    };
    for (long n = 0; n < 1000000; n++) {
        advance(a);
    }
    printf("%.15g\n%.15g\n%.15g\n%.15g\n%.15g\n", a[0], a[1], a[7], a[8], a[29]);
    return 0;
}
